(x, y, t) => {
  const cx = 240, cy = 120;
  const n1 = Math.sin(x*0.02+t*0.3)*Math.cos(y*0.015-t*0.2);
  const n2 = Math.cos(x*0.018-t*0.25)*Math.sin(y*0.022+t*0.35);
  const n3 = Math.sin((x+y)*0.012+t*0.15)*Math.cos((x-y)*0.01-t*0.1);
