  const wx2 = Math.sin((y+wx)*0.025+t*0.4)*10+Math.cos((x+wy)*0.02-t*0.3)*8;
  const wy2 = Math.cos((x+wx)*0.025-t*0.35)*10+Math.sin((y+wy)*0.02+t*0.45)*8;
  const sx = x+wx+wx2, sy = y+wy+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.85],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.05],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.95],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1,0.9],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+4)*45,0.075,1.8,1.0]
  ];
  let aS=0,iS=0,dS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    dS+=Math.cos(d*f*1.3-t*sp*0.8+0.7)*w;
  }
  const act=aS/8,inh=iS/8,diff=dS/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.08+Math.cos(sy*0.06+t)*3+t*1.5)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.25+Math.sin(dist*0.06-ang*5+t*0.8)*0.15;
  const raw=act-inh*0.7+bg*0.3+spiral+diff*0.2;
  const r1=Math.tanh(raw*2.2),r2=Math.tanh((raw-r1*0.5+diff*0.3)*1.8);
  const reaction=Math.tanh((r1+r2)*1.2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.cos(sx*0.12-sy*0.08+t*0.7)*0.3)*1.5)*0.3;
  const fine=Math.sin(sx*0.5+t*3)*Math.sin(sy*0.5-t*2.5)*0.05;
  const v=(reaction*0.6+cell*0.3+fine)*0.5+0.5;
  const pal=[[5,12,45],[12,45,85],[18,85,115],[25,140,135],[55,175,140],[140,195,120],[210,195,85],[225,165,65],[210,120,60],[185,75,65],[140,45,70],[85,25,65],[40,15,55],[5,12,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.65?1.12:1.0;
  const glow=Math.max(0,1-Math.abs(reaction))*0.15;
  const fl=lum*edge+glow;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*fl)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*fl)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*fl)|0
  ];
}
